/**
 * Creates a compute pass that enforces SDF volume boundaries on a 3D velocity grid.
 * Used for grid-based simulations like SmokeVolume.
 *
 * This enforces boundary conditions by:
 * 1. Sampling SDF at each grid cell
 * 2. Zeroing velocity if outside boundary (sdf > threshold)
 * 3. Projecting velocity to tangent direction near boundaries
 *
 * @param {THREE.Storage3DTexture} velocityTextureRead - Input velocity field
 * @param {THREE.Storage3DTexture} velocityTextureWrite - Output velocity field
 * @param {THREE.Storage3DTexture} sdfTexture - SDF 3D texture
 * @param {THREE.Matrix4} inverseBoundsMatrix - World to SDF local space
 * @param {THREE.Matrix4} boundsMatrix - SDF local to world space
 * @param {Object} options - Configuration
 * @param {number} options.gridResolution - Velocity grid resolution (e.g., 96)
 * @param {number} [options.threshold=0.0] - SDF boundary threshold
 * @param {number} [options.tangentProjection=0.5] - How much to project velocity to tangent (0=zero, 1=full projection)
 * @returns {*} TSL compute node
 */
export function createSDFGridBoundaryPass(velocityTextureRead: THREE.Storage3DTexture, velocityTextureWrite: THREE.Storage3DTexture, sdfTexture: THREE.Storage3DTexture, inverseBoundsMatrix: THREE.Matrix4, boundsMatrix: THREE.Matrix4, options?: {
    gridResolution: number;
    threshold?: number;
    tangentProjection?: number;
}): any;
